window.HOEREN_TESTS[63] = {"id":"im-reisebuero","name":"Im Reisebüro","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, hier ist das Reisebüro Sonnenschein. Ihre Buchung nach Italien ist bestätigt. Aber Achtung: Der Flug geht nicht um 10 Uhr, sondern wurde auf 14 Uhr verschoben. Nicht um 17 Uhr, wirklich um 14 Uhr. Das Hotel und alles andere bleibt gleich. Bitte am Flughafen drei Stunden vorher da sein. Schöne Reise!","gender":"f","q":"Wann geht der Flug jetzt?","opts":["Um 14 Uhr.","Um 10 Uhr.","Um 17 Uhr."],"correct":0},{"transcript":"Hallo Lisa, hier ist Anna. Ich war im Reisebüro und habe einen tollen Last-Minute-Urlaub gefunden. Eine Woche Griechenland, nur 400 Euro mit Flug und Hotel. Nicht Italien und nicht Spanien, wirklich Griechenland! Aber ich will nicht allein fahren. Hast du Lust und Zeit nächste Woche? Sag schnell Bescheid, das Angebot ist begrenzt!","gender":"f","q":"Wohin möchte Anna fahren?","opts":["Nach Griechenland.","Nach Italien.","Nach Spanien."],"correct":0},{"transcript":"Achtung Kunden: Wegen eines Streiks bei der Fluggesellschaft fallen am Freitag viele Flüge aus. Wenn Sie am Freitag fliegen, rufen Sie uns bitte heute noch an. Fahren Sie nicht zum Flughafen und warten Sie nicht, rufen Sie heute an! Wir suchen eine andere Verbindung für Sie. Buchungen für andere Tage sind nicht betroffen. Danke für Ihr Verständnis!","gender":"m","q":"Was sollen Freitags-Reisende tun?","opts":["Nichts tun.","Zum Flughafen fahren.","Heute anrufen."],"correct":2},{"transcript":"Hi Markus, hier ist Tom. Hey, ich plane eine Rundreise durch Deutschland mit dem Zug — keine Flüge, ist mir zu stressig. Nicht mit dem Flugzeug und nicht mit dem Auto, nur mit dem Zug. Das Reisebüro hat mir ein Bahn-Ticket für vier Wochen empfohlen. Möchtest du mit? Wir könnten viele Städte sehen. Überleg es dir, ruf zurück!","gender":"m","q":"Wie möchte Tom reisen?","opts":["Mit dem Flugzeug.","Mit dem Zug.","Mit dem Auto."],"correct":1},{"transcript":"Liebe Kunden: Wer früh bucht, spart Geld. Bei Buchung bis Ende Januar gibt es auf alle Sommerreisen 15 Prozent Frühbucherrabatt. Keine 10 und keine 20 Prozent, genau 15 Prozent. Außerdem ist die Reiserücktrittsversicherung kostenlos dabei. Kommen Sie vorbei und planen Sie schon jetzt Ihren Traumurlaub! Wir beraten Sie gern.","gender":"f","q":"Wie viel Rabatt gibt es bei früher Buchung?","opts":["10 Prozent.","20 Prozent.","15 Prozent."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wohin fahren sie in welchem Monat? Wählen Sie für jeden Monat einen Buchstaben (a–i).","lines":[{"speaker":"Lisa","gender":"f","text":"Hallo Lukas! Das Reisebüro hat die Sommertermine auf den Tisch gelegt."},{"speaker":"Lukas","gender":"m","text":"Schön, dass wir heute buchen. Ich habe dieses Jahr nur wenig Urlaub frei."},{"speaker":"Lisa","gender":"f","text":"Eine Städtereise mit zwei Nächten reicht uns im Mai. Wir bleiben in einer alten Stadt."},{"speaker":"Lukas","gender":"m","text":"Wäre eine Kreuzfahrt auf einem großen Schiff schöner für uns?"},{"speaker":"Lisa","gender":"f","text":"Nein. Eine Kreuzfahrt machen wir nicht. Das Schiff wäre uns einfach zu voll."},{"speaker":"Lukas","gender":"m","text":"Am Meer bleiben wir im Juni. Der Strandurlaub steht schon vorn auf dem Prospekt."},{"speaker":"Lisa","gender":"f","text":"Das Hotel liegt direkt am Wasser und morgens gibt es dort Brötchen."},{"speaker":"Lukas","gender":"m","text":"Die Kinder reden schon seit Wochen von einem großen Zelt."},{"speaker":"Lisa","gender":"f","text":"Der Platz am See ist im Juli schon für uns frei. Wir machen dort Camping."},{"speaker":"Lukas","gender":"m","text":"Wäre eine Safari in Afrika etwas für den Herbst?"},{"speaker":"Lisa","gender":"f","text":"Nein. Eine Safari in Afrika wollen wir nicht. Dafür ist unser Geld zu knapp."},{"speaker":"Lukas","gender":"m","text":"August zieht uns nach oben. Wir gehen wandern in den Bergen."},{"speaker":"Lisa","gender":"f","text":"Die Hütte ist schon für uns gebucht."},{"speaker":"Lukas","gender":"m","text":"Nach der Tour sind wir beide müde von der vielen Arbeit."},{"speaker":"Lisa","gender":"f","text":"Nur Ruhe und ein warmes Bad warten im September auf uns. Wir buchen einen Wellness-Urlaub."},{"speaker":"Lukas","gender":"m","text":"Dann gebe ich die fünf Monate heute an der Theke ab."}],"options":[{"letter":"a","text":"Kreuzfahrt"},{"letter":"b","text":"Safari in Afrika"},{"letter":"c","text":"Camping"},{"letter":"d","text":"Fahrradtour"},{"letter":"e","text":"Wellness-Urlaub"},{"letter":"f","text":"Skiurlaub"},{"letter":"g","text":"Wandern in den Bergen"},{"letter":"h","text":"Städtereise"},{"letter":"i","text":"Strandurlaub"}],"items":[{"person":"Mai","correct":"h"},{"person":"Juni","correct":"i"},{"person":"Juli","correct":"c"},{"person":"August","correct":"g"},{"person":"September","correct":"e"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag! Was kostet die Reise pro Person im Doppelzimmer?"},{"speaker":"Berater","gender":"m","text":"Im Doppelzimmer 600 Euro, im Einzelzimmer 750 Euro. 650 Euro gibt es nicht."},{"speaker":"Kundin","gender":"f","text":"750 Euro allein? Das ist viel. Gibt es einen Rabatt?"},{"speaker":"Berater","gender":"m","text":"Leider nein. Einzelzimmer mit Zuschlag, genau 750 Euro."},{"speaker":"Kundin","gender":"f","text":"Na gut, dann Einzelzimmer für 750 Euro. So ist es."}],"q":"Was kostet das Einzelzimmer pro Person?","opts":["600 Euro.","750 Euro.","650 Euro."],"correct":1},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag! Ist das Frühstück im Preis dabei?"},{"speaker":"Beraterin","gender":"f","text":"Ja, Frühstück ist inklusive. Aber nur das Frühstück, nichts anderes, im Preis."},{"speaker":"Mann","gender":"m","text":"Und das Abendessen? Ist das auch dabei?"},{"speaker":"Beraterin","gender":"f","text":"Nein, das kostet extra, 20 Euro pro Tag. Mittagessen auch extra, pro Person."},{"speaker":"Mann","gender":"m","text":"Verstanden, nur Frühstück! Das reicht mir völlig aus."}],"q":"Was ist im Preis inklusive?","opts":["Nichts.","Frühstück und Abendessen.","Nur das Frühstück."],"correct":2},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag! Brauche ich ein Visum für die Türkei?"},{"speaker":"Berater","gender":"m","text":"Nein, unbedingt kein Visum. Der Reisepass reicht völlig."},{"speaker":"Frau","gender":"f","text":"Wirklich nicht? Und wie lange darf ich dort bleiben?"},{"speaker":"Berater","gender":"m","text":"Bis zu 90 Tage ohne Visum, ganz legal und einfach."},{"speaker":"Frau","gender":"f","text":"90 Tage, das reicht völlig! Vielen Dank für die Auskunft! Tschüss!"}],"q":"Braucht die Frau ein Visum?","opts":["Ja, unbedingt.","Nein, der Reisepass reicht.","Nur für 90 Tage."],"correct":1},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag! Wann ist mein gebuchter Rückflug? Samstag?"},{"speaker":"Beraterin","gender":"f","text":"Am Sonntag um 18 Uhr. Nicht Samstag, wirklich Sonntag."},{"speaker":"Kunde","gender":"m","text":"Geht auch ein Tag später, also Montag?"},{"speaker":"Beraterin","gender":"f","text":"Ja, Montag geht auch, aber 50 Euro mehr. Überlegen Sie es sich gut."},{"speaker":"Kunde","gender":"m","text":"Nein, dann bleibe ich sicher bei Sonntag um 18 Uhr. Danke schön!"}],"q":"Wann ist der gebuchte Rückflug?","opts":["Sonntag.","Samstag.","Montag."],"correct":0},{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag! Ich möchte eine Reise stornieren, nicht buchen."},{"speaker":"Berater","gender":"m","text":"Oh! Haben Sie eine Versicherung? Eine Reiserücktrittsversicherung?"},{"speaker":"Kundin","gender":"f","text":"Ja, die habe ich. Verlängern will ich sie nicht, wirklich stornieren."},{"speaker":"Berater","gender":"m","text":"Gut, dann bekommen Sie das Geld zurück. Kommen Sie morgen vorbei."},{"speaker":"Kundin","gender":"f","text":"Morgen? Geht auch heute? Ich habe Zeit."},{"speaker":"Berater","gender":"m","text":"Heute geht auch. Bringen Sie die Papiere mit!"}],"q":"Was möchte die Kundin tun?","opts":["Eine Reise buchen.","Eine Reise verlängern.","Eine Reise stornieren."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Sommer, einer Reiseberaterin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Sommer, warum geht man noch ins Reisebüro? Ist Internet nicht billiger?"},{"speaker":"Sommer","gender":"f","text":"Wegen der persönlichen Beratung, ganz klar. Im Internet ist man allein mit tausend Angeboten. Bei uns hilft ein Mensch, der alles kennt und ehrlich berät."},{"speaker":"Reporter","gender":"m","text":"Welche Reiseziele sind beliebt? Wohin fahren die Deutschen?"},{"speaker":"Sommer","gender":"f","text":"Spanien und Italien immer, das sind Klassiker. Aber auch ferne Länder wie Thailand kommen wieder, nach Corona besonders. Die Leute wollen wieder weit weg."},{"speaker":"Reporter","gender":"m","text":"Was ist der häufigste Fehler?"},{"speaker":"Sommer","gender":"f","text":"Die Leute buchen zu spät, das ist der Fehler. Dann ist alles teuer und voll. Wer früh bucht, spart Geld, manchmal die Hälfte. Das sage ich allen Kunden."},{"speaker":"Reporter","gender":"m","text":"Reisen Sie selbst gern?"},{"speaker":"Sommer","gender":"f","text":"Ja, sehr, ich liebe Reisen. Am liebsten dorthin, wo wenige Touristen sind. Kleine Dörfer, Natur, Ruhe."},{"speaker":"Reporter","gender":"m","text":"Was raten Sie für die nächste Reise?"},{"speaker":"Sommer","gender":"f","text":"Probieren Sie etwas Neues, nicht immer das Gleiche. Und nehmen Sie nicht zu viel Gepäck mit, ein Koffer reicht, wirklich! Kein Stress: zwei Koffer braucht wirklich kein Mensch. Glauben Sie mir!"}],"items":[{"q":"Frau Sommer findet, man soll möglichst spät buchen.","correct":"nein"},{"q":"Im Reisebüro bekommt man eine persönliche Beratung.","correct":"ja"},{"q":"Wer früh bucht, spart Geld.","correct":"ja"},{"q":"Sie reist am liebsten dort, wo viele Touristen sind.","correct":"nein"},{"q":"Sie rät, nicht zu viel Gepäck mitzunehmen.","correct":"ja"}]}]};
